import streamlit as st

st.title("Calculadora imc 📱")
st.subheader("Feito com Streamlit ")

altura = st.number_input("digite a sua altura", min_value=0.0)
peso = st.number_input("digite o seu peso", min_value=0.0)

imc = peso / altura ** 2

if st.button("calcular"):
  
   if imc < 18.5:
      st.image("https://www.bing.com/th/id/OGC.3378f4e4f319e0d54e50f49e1c56afbe?o=7&pid=1.7&rm=3&rurl=https%3a%2f%2fmedia.tenor.com%2fJZxEu1mBeGwAAAAd%2fesqueleto.gif&ehk=lhve0pHn3xadkoWgWD0j5zP1PXDeV%2bKlp2vg50fSqgs%3d",width=300)
      st.error("Abaixo do peso ☠️")
   elif imc < 24.9:
      st.image("https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSlpgKTpxdal83peAzS03awYhleETOq-7zxI4foUignFHt9IpxIe_7mkAY&s",widt=300)
      st.write("Peso normal 👍")
   elif imc < 29.9:
      st.write("sobrepeso 👍")
      st.image("data:image/png;base64,",width=300)

   elif imc < 34.9:
      st.write("obesidade gral 1 😬")
      st.image("https://www.google.com/imgres?q=%20meme%20do%20luffy%20barigudo&imgurl=https%3A%2F%2Fi.redd.it%2F7h9us9xgk4f61.jpg&imgrefurl=https%3A%2F%2Fwww.reddit.com%2Fr%2FMemePiece%2Fcomments%2Flb5oys%2Fdont_mind_me_just_a_fat_luffy_passing_by%2F%3Ftl%3Dpt-br&docid=oKiDxLEzVifFeM&tbnid=Pg3BWl82bSHMQM&vet=12ahUKEwjQp5nCu5CUAxUprZUCHRFzIXIQnPAOegQIIhAB..i&w=355&h=285&hcb=2&ved=2ahUKEwjQp5nCu5CUAxUprZUCHRFzIXIQnPAOegQIIhAB",width=300)

   elif imc < 39.9:
      st.write("obesiade gral 2 😯")   
      st.image("https://www.google.com/imgres?q=meme%20do%20luffy%20para%20de%20cumer&imgurl=https%3A%2F%2Fi.ytimg.com%2Fvi%2FVfXYOUn_bIs%2Fmaxresdefault.jpg&imgrefurl=https%3A%2F%2Fwww.youtube.com%2Fwatch%3Fv%3DVfXYOUn_bIs&docid=HpYq8HWPxSSFzM&tbnid=jfT__QV-7VqbLM&vet=12ahUKEwi27Ljmu5CUAxVop5UCHffxOQkQnPAOegQIHRAB..i&w=1280&h=720&hcb=2&ved=2ahUKEwi27Ljmu5CUAxVop5UCHffxOQkQnPAOegQIHRAB",width=300)

   else:
      st.write("obesiade gral 3 😱")
      st.image("https://www.google.com/imgres?q=meme%20do%20luffy%20para%20de%20cumer&imgurl=https%3A%2F%2Fi.redd.it%2Fhrts0mlrhgfa1.jpg&imgrefurl=https%3A%2F%2Fwww.reddit.com%2Fr%2FMemePiece%2Fcomments%2F10qcqu1%2Fquick_question_has_luffy_ever_been_truly_full_and%2F%3Ftl%3Dpt-br&docid=mMdPHQhzWySFjM&tbnid=q19o3ZpiiAfQ5M&vet=12ahUKEwi27Ljmu5CUAxVop5UCHffxOQkQnPAOegQILBAB..i&w=300&h=168&hcb=2&ved=2ahUKEwi27Ljmu5CUAxVop5UCHffxOQkQnPAOegQILBAB",width=300)
